namespace NovaHarvest.Core.NPC; public sealed class NPCManager { readonly Dictionary<string,NPC> _npcs=new();public IReadOnlyCollection<NPC> AllNPCs=>_npcs.Values;public bool Add(NPC n){if(n is null||string.IsNullOrWhiteSpace(n.Id)||_npcs.ContainsKey(n.Id))return false;_npcs.Add(n.Id,n);return true;}public NPC? Find(string id)=>_npcs.TryGetValue(id,out var n)?n:null;public IReadOnlyList<NPC> GetByState(NPCState s)=>_npcs.Values.Where(n=>n.State==s).ToList();public IReadOnlyList<NPC> GetByProfession(NPCProfession p)=>_npcs.Values.Where(n=>n.Profession==p).ToList();public IReadOnlyList<NPC> GetColonyMembers()=>GetByState(NPCState.LivingInColony);public bool Exists(string id)=>_npcs.ContainsKey(id);}
